package gateway

import (
	"os"
	"strings"

	"github.com/TrebuchetDynamics/gormes-agent/internal/platform/cli/gormescli/remoteruntime"
)

func ResolveRemoteURL(flagValue string) string {
	if raw := strings.TrimSpace(flagValue); raw != "" {
		return raw
	}
	for _, key := range []string{"GORMES_TUI_GATEWAY_URL", "HERMES_TUI_GATEWAY_URL"} {
		if raw := strings.TrimSpace(os.Getenv(key)); raw != "" {
			return raw
		}
	}
	return ""
}

func ResolveRemoteSidecarURL() string {
	for _, key := range []string{"GORMES_TUI_SIDECAR_URL", "HERMES_TUI_SIDECAR_URL"} {
		if raw := strings.TrimSpace(os.Getenv(key)); raw != "" {
			return raw
		}
	}
	return ""
}

func IsWebSocketRemoteURL(raw string) bool {
	return remoteruntime.IsWebSocketRemoteURL(raw)
}

package gateway

import "testing"

func TestResolveRemoteURLPrefersFlagThenEnvironment(t *testing.T) {
	t.Setenv("GORMES_TUI_GATEWAY_URL", "ws://gormes-gateway/api/ws")
	t.Setenv("HERMES_TUI_GATEWAY_URL", "ws://hermes-gateway/api/ws")
	if got := ResolveRemoteURL(" http://flag-gateway/events "); got != "http://flag-gateway/events" {
		t.Fatalf("ResolveRemoteURL(flag) = %q; want trimmed flag", got)
	}
	if got := ResolveRemoteURL(""); got != "ws://gormes-gateway/api/ws" {
		t.Fatalf("ResolveRemoteURL(env) = %q; want GORMES_TUI_GATEWAY_URL", got)
	}
}

func TestResolveRemoteURLAcceptsHermesCompatibilityEnvironment(t *testing.T) {
	t.Setenv("GORMES_TUI_GATEWAY_URL", "")
	t.Setenv("HERMES_TUI_GATEWAY_URL", " ws://hermes-gateway/api/ws?token=secret ")
	if got := ResolveRemoteURL(""); got != "ws://hermes-gateway/api/ws?token=secret" {
		t.Fatalf("ResolveRemoteURL(HERMES_TUI_GATEWAY_URL) = %q", got)
	}
}

package preflight

import (
	"context"
	"os"

	"github.com/TrebuchetDynamics/gormes-agent/internal/platform/doctor"
)

type StartupPreflightOptions struct {
	WorkDir string
}

func RunNativeStartupPreflight(_ context.Context, opts StartupPreflightOptions) doctor.CheckResult {
	if opts.WorkDir == "" {
		if wd, err := os.Getwd(); err == nil {
			opts.WorkDir = wd
		}
	}
	return DoctorStatus()
}

func DoctorStatus() doctor.CheckResult {
	return doctor.CheckResult{
		Name:    "Native TUI",
		Status:  doctor.StatusPass,
		Summary: "available: Go-native Bubble Tea TUI compiled into gormes",
		Items: []doctor.ItemInfo{
			{
				Name:   "runtime",
				Status: doctor.StatusPass,
				Note:   "local startup uses the compiled Go Bubble Tea shell",
			},
			{
				Name:   "offline",
				Status: doctor.StatusPass,
				Note:   "offline mode keeps the same native TUI path without a JavaScript bundle build step",
			},
			{
				Name:   "remote",
				Status: doctor.StatusPass,
				Note:   "remote streaming via --remote <url> consumes native Gormes turn events over SSE or websocket attach via GORMES_TUI_GATEWAY_URL/HERMES_TUI_GATEWAY_URL; without a remote URL the local Bubble Tea path remains the runtime",
			},
		},
	}
}

package preflight

import (
	"strings"
	"testing"
)

func TestDoctorTUIStatusReportsRemoteDegradedMode(t *testing.T) {
	got := DoctorStatus().Format()
	lower := strings.ToLower(got)
	for _, want := range []string{"native tui", "go-native bubble tea", "remote", "websocket"} {
		if !strings.Contains(lower, want) {
			t.Errorf("doctor TUI status missing %q:\n%s", want, got)
		}
	}
}

